SELECT quantity_bucket, quantity_count, unique_products FROM (SELECT CASE WHEN quantity >= 216 THEN 'high' WHEN quantity >= 35 THEN 'mid' ELSE 'low' END AS quantity_bucket, COUNT(quantity) AS quantity_count, COUNT(DISTINCT quantity) AS unique_products FROM inventory WHERE last_restock <= '2023-03-24' GROUP BY CASE WHEN quantity >= 216 THEN 'high' WHEN quantity >= 35 THEN 'mid' ELSE 'low' END) AS agg WHERE unique_products < 4;
